import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/slog.html","title":"slog","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":2.24,"words":673},"filePathRelative":"slog.md"}`),a={name:`slog.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="slog" tabindex="-1"><a class="header-anchor" href="#slog"><span>slog</span></a></h1><p><a href="./作業ログ.html">作業ログ</a>, <a href="./ノート.html">ノート</a></p><h2 id="slogとは" tabindex="-1"><a class="header-anchor" href="#slogとは"><span>slogとは</span></a></h2><p>slogとは、以下の決まりで書いていく作業メモの事。SagyouLOGでslog。</p><ul><li>単なるmdファイルを特定のフォルダ下に置いていく</li><li>mdファイルはキーワードと日付から生成されるファイル名</li><li>ファイルの先頭は必ずその作業のタイトルを書く</li></ul><p>具体的な形式などは以下の各項目を参照のこと。</p><h3 id="哲学" tabindex="-1"><a class="header-anchor" href="#哲学"><span>哲学</span></a></h3><p><a href="./作業ログ.html">作業ログ</a>をいい感じにローカルに書いていくのに必要な決まりごとを考えた。考察は<a href="./作業ログ.html">作業ログ</a>の方にも書いてある。</p><ul><li>気軽に新規の作業ログを開始出来る <ul><li>タイトルを考える前に始められる（newfile.commandをダブルクリックするだけ）</li><li>ファイル名のキーワードはあくまでCmd-pなどで引っ掛けるためだけに使用、あまり考えずに適当に</li><li>タイトルは後で変更してもファイル名に影響無し（始めた後にタイトルを考えられるように） <ul><li>タイトルは後からより適切なものが思いつく都度ちょくちょく変更していく</li></ul></li></ul></li><li>一つの作業ログに何を書き足してもほかの作業をしている時は目に触れない <ul><li>1作業1ファイル</li><li>大量のログなどを貼っても他のメモを邪魔しない</li></ul></li><li>ログやコマンド、コード片などを何も考えずにコピペしていける <ul><li>ゆるいmdフォーマットだがmd違反があっても気にしない、プレーンテキスト</li></ul></li><li>フォルダごと<a href="./Syncthing.html">Syncthing</a>で同期</li></ul><h2 id="新規ファイル作成スクリプト" tabindex="-1"><a class="header-anchor" href="#新規ファイル作成スクリプト"><span>新規ファイル作成スクリプト</span></a></h2><p>ファイル名は2025_1212_211312-some_key_word.md とかにする。以下のスクリプトで作る。</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token shebang important">#!/usr/bin/env bash</span></span>
<span class="line"></span>
<span class="line"><span class="token assign-left variable">BASENAME</span><span class="token operator">=</span><span class="token variable"><span class="token variable">\`</span><span class="token function">date</span> <span class="token string">&quot;+%Y_%m%d_%H%M%S&quot;</span><span class="token variable">\`</span></span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span class="token assign-left variable">DEST</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token function">dirname</span> $0<span class="token variable">)</span></span></span>
<span class="line"><span class="token assign-left variable">FILENAME</span><span class="token operator">=</span><span class="token string">&quot;<span class="token variable">$DEST</span>/<span class="token variable">\${BASENAME}</span>-blank.md&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token variable">$FILENAME</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;# &quot;</span> <span class="token operator">&gt;</span> <span class="token variable">$FILENAME</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Mac上ではnewfile.commandというファイルでslogのディレクトリに置いて、Finderからダブルクリックで作っている。 名前を考える前にダブルクリックで始められる、というのが結構良い。</p><p>なお、ファイル名にキーワードっぽいものが入ってないとCmd-pで開く時などに困る場合もあるので、その場合はハイフンで区切ってアンダーバー区切りにする。例えば以下。</p><p>2025_1212_211312-some_id_example.md</p><p>区切りがハイフンなのはこれでsedで一発で削れるように。</p><h2 id="一覧を選ぶシェルスクリプト" tabindex="-1"><a class="header-anchor" href="#一覧を選ぶシェルスクリプト"><span>一覧を選ぶシェルスクリプト</span></a></h2><p>Copilotに書かせてみたらfzfを使ったいい感じのが出来た。</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token shebang important">#!/usr/bin/env bash</span></span>
<span class="line"></span>
<span class="line"><span class="token assign-left variable">DIR</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token function">dirname</span> $0<span class="token variable">)</span></span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 一時ファイルに日付とタイトルを抽出</span></span>
<span class="line"><span class="token assign-left variable">LIST</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token keyword">for</span> <span class="token for-or-select variable">file</span> <span class="token keyword">in</span> <span class="token string">&quot;<span class="token variable">$DIR</span>&quot;</span>/*.md<span class="token punctuation">;</span> <span class="token keyword">do</span></span>
<span class="line">    <span class="token assign-left variable">title</span><span class="token operator">=</span><span class="token punctuation">$(</span>head <span class="token parameter variable">-n</span> <span class="token number">1</span> <span class="token string">&quot;<span class="token variable">$file</span>&quot;</span> <span class="token operator">|</span> <span class="token function">sed</span> <span class="token string">&#39;s/^# *//&#39;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token assign-left variable">date</span><span class="token operator">=</span><span class="token punctuation">$(</span>basename <span class="token string">&quot;<span class="token variable">$file</span>&quot;</span> .md <span class="token operator">|</span> <span class="token function">sed</span> <span class="token string">&#39;s/-.*//&#39;</span> <span class="token operator">|</span> <span class="token function">sed</span> <span class="token string">&#39;s/_/ /g&#39;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;<span class="token variable">$date</span> | <span class="token variable">$title</span> | <span class="token variable">$file</span>&quot;</span></span>
<span class="line"><span class="token keyword">done</span><span class="token variable">)</span></span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># fzfで選択</span></span>
<span class="line"><span class="token assign-left variable">SELECTED</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token builtin class-name">echo</span> <span class="token string">&quot;<span class="token variable">$LIST</span>&quot;</span> <span class="token operator">|</span> fzf --with-nth<span class="token operator">=</span><span class="token number">1,2</span> <span class="token parameter variable">--delimiter</span><span class="token operator">=</span><span class="token string">&quot;|&quot;</span> <span class="token parameter variable">--preview</span> <span class="token string">&#39;head -n 20 {3}&#39;</span> --preview-window<span class="token operator">=</span>down:wrap<span class="token variable">)</span></span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># ファイルパスを抽出して開く</span></span>
<span class="line"><span class="token assign-left variable">FILE</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token builtin class-name">echo</span> <span class="token string">&quot;<span class="token variable">$SELECTED</span>&quot;</span> <span class="token operator">|</span> <span class="token function">awk</span> <span class="token parameter variable">-F</span> <span class="token string">&#39;|&#39;</span> <span class="token string">&#39;{print $3}&#39;</span> <span class="token operator">|</span> <span class="token function">xargs</span><span class="token variable">)</span></span></span>
<span class="line"><span class="token punctuation">[</span> <span class="token parameter variable">-n</span> <span class="token string">&quot;<span class="token variable">$FILE</span>&quot;</span> <span class="token punctuation">]</span> <span class="token operator">&amp;&amp;</span> <span class="token function">open</span> <span class="token string">&quot;<span class="token variable">$FILE</span>&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>タイトルと日付のリストで、上にフォーカスを当てると先頭20行が表示される。すげー便利。 これもFinderからダブルクリックで使っている。</p><p>こういうの書かせるにはLLMは最強だな。</p><p>サマリーが無いが素のPowerShellのバージョンも作ってもらった。</p><div class="language-powershell line-numbers-mode" data-highlighter="prismjs" data-ext="powershell"><pre><code class="language-powershell"><span class="line"><span class="token variable">$dir</span> = <span class="token function">Split-Path</span> <span class="token variable">$PSCommandPath</span></span>
<span class="line"></span>
<span class="line"><span class="token variable">$items</span> = <span class="token function">Get-ChildItem</span> <span class="token string">&quot;<span class="token variable">$dir</span>&quot;</span> <span class="token operator">-</span><span class="token keyword">Filter</span> <span class="token operator">*</span><span class="token punctuation">.</span>md <span class="token punctuation">|</span> <span class="token function">ForEach-Object</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token variable">$title</span> = <span class="token punctuation">(</span><span class="token function">Get-Content</span> <span class="token variable">$_</span><span class="token punctuation">.</span>FullName <span class="token operator">-</span>TotalCount 1<span class="token punctuation">)</span> <span class="token operator">-replace</span> <span class="token string">&#39;^#\\s*&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;&#39;</span></span>
<span class="line">    <span class="token variable">$date</span>  = <span class="token variable">$_</span><span class="token punctuation">.</span>BaseName <span class="token operator">-replace</span> <span class="token string">&#39;-.*&#39;</span><span class="token punctuation">,</span><span class="token string">&#39;&#39;</span> <span class="token operator">-replace</span> <span class="token string">&#39;_&#39;</span><span class="token punctuation">,</span><span class="token string">&#39; &#39;</span></span>
<span class="line">    <span class="token namespace">[PSCustomObject]</span>@<span class="token punctuation">{</span></span>
<span class="line">        Date  = <span class="token variable">$date</span></span>
<span class="line">        Title = <span class="token variable">$title</span></span>
<span class="line">        Path  = <span class="token variable">$_</span><span class="token punctuation">.</span>FullName</span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token variable">$selected</span> = <span class="token variable">$items</span> <span class="token punctuation">|</span> <span class="token function">Out-GridView</span> <span class="token operator">-</span>Title <span class="token string">&quot;Select Markdown&quot;</span> <span class="token operator">-</span>PassThru</span>
<span class="line"></span>
<span class="line"><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$selected</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token function">Start-Process</span> <span class="token variable">$selected</span><span class="token punctuation">.</span>Path</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Out-GridViewはなかなかいいよな。</p><h2 id="使ってみた感想" tabindex="-1"><a class="header-anchor" href="#使ってみた感想"><span>使ってみた感想</span></a></h2><p>以下に雑多な感想などを書いてみる</p><h3 id="結構いい感じだ-2026-01-04-日" tabindex="-1"><a class="header-anchor" href="#結構いい感じだ-2026-01-04-日"><span>結構いい感じだ 2026-01-04 (日)</span></a></h3><p>単にちょっとした決まりごとを決めてシェルスクリプトを二つ書いただけなのだが、凄くいい感じだ。 WIkiなどに統合するよりも単なるテキストファイルにしてVSCodeで書く方が良い。 正しい事を始めた感じがする。</p><p>今の所スクショが貼れないが、<a href="./MdImgr.html">MdImgr</a>使って貼れるように考えてもいいかもしれない。この辺は必要になったら考える。 先に始められているのがこのコンセプトの正しさを証明している気がする。</p><h3 id="日報との使い分け-2026-01-06-火" tabindex="-1"><a class="header-anchor" href="#日報との使い分け-2026-01-06-火"><span>日報との使い分け 2026-01-06 (火)</span></a></h3><p>slogを書いていると日報的な毎日何やったかを書く作業ログの記述が過小になりがちという問題があるかもしれない。 今やってる作業がMFGStudioのオープンソース化という、社内ライブラリの依存を粛々と切っていくだけの作業なのでそうなっているだけかもしれないが。</p><p>1日にやった事箇条書き、一週間のまとめ、一ヶ月のまとめ、くらいはやっぱり別に欲しいんだよなぁ。</p><h3 id="皆様の反応" tabindex="-1"><a class="header-anchor" href="#皆様の反応"><span>皆様の反応</span></a></h3><p>slogの話をしたらomo先生は以下のような感じとか。</p><p><a href="https://records.dodgson.org/2026/01/05/perbug-pages/" target="_blank" rel="noopener noreferrer">Per-Bug Pages - 2026-01-05 / Spinach Forest</a></p><p>違う部分もあるがモチベーションと解決策にはかなり近いものがある。 バグとかチケットごとのテキストファイルを専用のフォルダに置く、というのは何かの答えなのかもしれない。</p><p><a href="https://blog.kyanny.me/entry/2026/01/06/150648#gsc.tab=0" target="_blank" rel="noopener noreferrer">Per-task notes - @kyanny&#39;s blog</a></p><p>元々<a href="./作業ログ.html">作業ログ</a>のページはkyanny&#39;s blogのやり方のリンクから始まっている事からも明らかなように、影響はかなり受けているかもしれない。 細部はそれぞれ違っていて、その違いはそれぞれの環境の違いから来るのだろうな。</p><ul><li>Daily Notes的なものが別にある</li><li>タスクごとに別個のmdファイルがある</li><li>特定のフォルダに置く</li></ul><p>このくらいは結論として良いのかもしれない。</p><h3 id="やはりファイル名にキーワードは要るか-2026-01-23-金" tabindex="-1"><a class="header-anchor" href="#やはりファイル名にキーワードは要るか-2026-01-23-金"><span>やはりファイル名にキーワードは要るか 2026-01-23 (金)</span></a></h3><p>キーワードをつけずにファイルを作れるのが重要と思ったが、やはりキーワードがついている方がVSCodeで複数タブを行き来する時には便利だな、という結論になり、キーワードを入れられるようにする。</p><p>ハイフンで区切ってキーワードをつける。listのスクリプトにその対応を入れる。 ただキーワードはオプショナルにしてファイルを作る時にはつけない。気が向いた時に後から足す方針で。</p><h3 id="slogで書いてやがて外に移動というパターン-2026-02-06-金" tabindex="-1"><a class="header-anchor" href="#slogで書いてやがて外に移動というパターン-2026-02-06-金"><span>slogで書いてやがて外に移動というパターン 2026-02-06 (金)</span></a></h3><p>slogでとりあえず書いてみて、ある程度書いたら「これはissueの方がいいな」とか「これはGitHub Wikiに移動したいな」というのがちょくちょく出てきて移動している。 大体半分くらいはそうやって移動されたか。</p><p>このある程度育ってきたら移動する、というのは、最初からそれらでやっておけばいい話ではあるはずだが、 そうした事を最初に考える前にとりあえずslogで始められる、というのが重要に思う。 ちょっと始めるのが面倒だな、という時に漏れてしまうものをslogが上手い事拾ってくれている気がする。 これまで書かずに済ませてしまっていた事をちゃんと書くようになった。</p><p>むしろ他に移動したくなったらすぐ移動出来るのもslogの良い所に思う。というのは各ファイルに依存が無いので、削除なども自由に出来るから。</p>`,47)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};